def fact_for(profile, language):
    """Known catalog entries use audited text; unseen entries get a source quote."""
    fact = FACTS.get(profile['id'])
    if fact:
        return fact[1 if language == 'kk' else 0]
    # Preserve the first source clause for future entries; never invent a translation.
    clause = profile['description'].split('.')[0].strip().rstrip('!?…')
    prefix = 'Каталогтағы сипаттама: ' if language == 'kk' else 'В описании каталога: '
    return prefix + '«' + clause + '»'
